function validate(input) {
  const [tables] = input;
  for (const name of ['SchoolA', 'SchoolB', 'SchoolC']) {
    const seen = new Set();
    for (const [id, student] of tables[name] ?? []) {
      if (id === null || student === null) return `${name} rows may not contain null.`;
      if (seen.has(id)) return `student_id ${id} appears twice in ${name}.`;
      seen.add(id);
    }
  }
  return null;
}

