function generate(rand, size) {
  const small = size === 'small';
  const names = ['Alice', 'Bob', 'Tom', 'Jerry', 'Mia', 'Noah', 'Olga', 'Pablo', 'Quinn', 'Rosa', 'Sam', 'Tina'];
  const pool = small ? names.slice(0, 5) : names;
  const idRange = small ? 6 : 40;
  const school = () => {
    const count = small ? Math.floor(rand() * 5) : 20;
    const ids = new Set(), rows = [];
    while (rows.length < count) {
      const id = 1 + Math.floor(rand() * idRange);
      if (ids.has(id)) continue;
      ids.add(id);
      rows.push([id, pool[Math.floor(rand() * pool.length)]]);
    }
    return rows;
  };
  return [{ SchoolA: school(), SchoolB: school(), SchoolC: school() }];
}
